/// Node IDs returned after building the grateful dead graph.
pub struct GratefulGraphIds {
    pub song_ids: Vec<NodeId>,
    pub artist_ids: Vec<NodeId>,
    /// Maps song/artist name → NodeId for quick lookup.
    pub name_to_id: HashMap<String, NodeId>,
}

/// Create an `InMemoryGraphStore` pre-populated with the TinkerPop
/// "grateful dead" graph on a graph named `"grateful"`.
pub fn create_grateful_graph() -> (InMemoryGraphStore, GratefulGraphIds) {
    let store = InMemoryGraphStore::new();
    store.create_graph("grateful").unwrap();

    let mut song_ids = Vec::with_capacity(SONGS.len());
    let mut name_to_id = HashMap::new();

    for &(name, song_type, performances) in &SONGS {
        let mut props = IndexMap::new();
        props.insert("name".to_string(), Value::Str(name.into()));
        props.insert("songType".to_string(), Value::Str(song_type.into()));
        props.insert("performances".to_string(), Value::Int(performances));
        let id = store
            .create_node("grateful", vec!["song".to_string()], props)
            .unwrap();
        name_to_id.insert(name.to_string(), id);
        song_ids.push(id);
    }

    let mut artist_ids = Vec::with_capacity(ARTISTS.len());
    for &name in &ARTISTS {
        let mut props = IndexMap::new();
        props.insert("name".to_string(), Value::Str(name.into()));
        let id = store
            .create_node("grateful", vec!["artist".to_string()], props)
            .unwrap();
        name_to_id.insert(name.to_string(), id);
        artist_ids.push(id);
    }

    for &(src, dst, weight) in &FOLLOWED_BY {
        let mut props = IndexMap::new();
        props.insert("weight".to_string(), Value::Int(weight));
        store
            .create_edge(
                "grateful",
                song_ids[src as usize],
                song_ids[dst as usize],
                "followedBy".to_string(),
                props,
            )
            .unwrap();
    }

    for &(song, artist) in &SUNG_BY {
        store
            .create_edge(
                "grateful",
                song_ids[song as usize],
                artist_ids[artist as usize],
                "sungBy".to_string(),
                IndexMap::new(),
            )
            .unwrap();
    }

    for &(song, artist) in &WRITTEN_BY {
        store
            .create_edge(
                "grateful",
                song_ids[song as usize],
                artist_ids[artist as usize],
                "writtenBy".to_string(),
                IndexMap::new(),
            )
            .unwrap();
    }

    let ids = GratefulGraphIds {
        song_ids,
        artist_ids,
        name_to_id,
    };

    (store, ids)
}
